import{_ as e,o as t,c as n,a2 as i}from"./chunks/framework.CqGS6Fr9.js";const p=JSON.parse('{"title":"Localization","description":"","frontmatter":{"pageId":"developers/localization","contentRevision":2},"headers":[],"relativePath":"en/developers/localization.md","filePath":"en/developers/localization.md"}'),s={name:"en/developers/localization.md"};function o(r,a,l,c,d,h){return t(),n("div",null,[...a[0]||(a[0]=[i('<h1 id="localization" tabindex="-1">Localization <a class="header-anchor" href="#localization" aria-label="Permalink to &quot;Localization&quot;">​</a></h1><p>Applies to: Rimlink 0.8.1 · RimWorld 1.7 · protocol 1.</p><h2 id="usage" tabindex="-1">Usage <a class="header-anchor" href="#usage" aria-label="Permalink to &quot;Usage {#usage}&quot;">​</a></h2><p>Every mod-facing string is a keyed string under mod/Languages/English and Russian. Add both versions in the same task with matching keys/placeholders; do not translate technical identifiers. Inspect actual dialogs, label lengths and grammar in context.</p><p>The wiki uses matching pageIds and shared explicit anchors in RU/EN. Both articles carry the same contentRevision. A semantic change requires updating both versions and the manifest, not replacing English with a link to Russian. Navigation labels are translated too. Search runs locally and normalizes case and ё/е.</p><p>Run test:checks and check:content after translating; manually compare meaning, warnings and numeric limits. Matching metadata does not prove translation quality.</p><h2 id="translation-work" tabindex="-1">Verify translation as behavior <a class="header-anchor" href="#translation-work" aria-label="Permalink to &quot;Verify translation as behavior {#translation-work}&quot;">​</a></h2><p>Choose a key and parameter meaning before adding matching English/Russian placeholders. Verify plurals, substitutions, button length and warnings before dangerous actions. Never translate technical IDs, configuration keys or paths.</p><p>Translate the full wiki scenario, not just its title. Compare numbers, prerequisites, actors and failure consequences. Increment shared contentRevision and update coverage questions/sources. Shared anchors preserve language switching with hashes. Structural PASS cannot establish semantic translation quality.</p><h2 id="limits" tabindex="-1">Limits and safety <a class="header-anchor" href="#limits" aria-label="Permalink to &quot;Limits and safety {#limits}&quot;">​</a></h2><p>Do not hard-code C# UI text instead of localization keys. Do not add external search/analytics for localization. Examples must not contain real tokens, personal saves or private logs.</p><h2 id="related" tabindex="-1">See also <a class="header-anchor" href="#related" aria-label="Permalink to &quot;See also {#related}&quot;">​</a></h2><ul><li><a href="./contributing">Contributing and wiki maintenance</a></li><li><a href="./testing">Testing and acceptance</a></li><li><a href="./../glossary">Glossary</a></li></ul>',13)])])}const m=e(s,[["render",o]]);export{p as __pageData,m as default};
